export type Recipient = {
  id: string
  name: string
  accountMasked: string
  currency: string
  initials: string
}

export const RECENT_RECIPIENTS: Recipient[] = [
  { id: "r1", name: "Amara Okafor", accountMasked: "•••• 4821", currency: "EUR", initials: "AO" },
  { id: "r2", name: "Liam Chen", accountMasked: "•••• 1190", currency: "GBP", initials: "LC" },
  { id: "r3", name: "Priya Nair", accountMasked: "•••• 7734", currency: "INR", initials: "PN" },
  { id: "r4", name: "Diego Fernandez", accountMasked: "•••• 0256", currency: "MXN", initials: "DF" },
]

/** Fixed mock exchange rate per receive currency, quoted against USD. */
export const EXCHANGE_RATES: Record<string, number> = {
  EUR: 0.92,
  GBP: 0.79,
  INR: 83.12,
  MXN: 17.04,
}

export type SendMoneyData = {
  recipientId: string | null
  sendAmount: string
  sendCurrency: string
}

export const SEND_MONEY_INITIAL: SendMoneyData = {
  recipientId: null,
  sendAmount: "",
  sendCurrency: "USD",
}

export const SEND_MONEY_STEPS = ["recipient", "amount", "review"] as const
export type SendMoneyStep = (typeof SEND_MONEY_STEPS)[number]

export type SendMoneyStepProps = {
  data: SendMoneyData
  patch: (p: Partial<SendMoneyData>) => void
  next: () => void
  back: () => void
  goTo: (i: number) => void
}

export function findRecipient(id: string | null): Recipient | undefined {
  return RECENT_RECIPIENTS.find((r) => r.id === id)
}

/** Flat fee + a spread baked into the quoted rate — mirrors a typical transfer fee breakdown. */
export function calculateFee(sendAmount: number): number {
  if (!sendAmount || sendAmount <= 0) return 0
  return Math.round((sendAmount * 0.005 + 2) * 100) / 100
}

export function calculateReceiveAmount(sendAmount: number, currency: string): number {
  const rate = EXCHANGE_RATES[currency] ?? 1
  const fee = calculateFee(sendAmount)
  const net = Math.max(0, sendAmount - fee)
  return Math.round(net * rate * 100) / 100
}

