"use client"

import type { KeyboardEvent } from "react"
import { Badge } from "@atlas/ui-web/primitives/Badge/Badge"
import type { Recipient } from "../schema"

/**
 * ListRow gap (CAND-002 in atlas/state/candidates.json) — no list-row component
 * exists in the index. Composed from a pressable div + a leading initials
 * circle (Avatar gap, CAND-001) + title/subtitle + a trailing Badge.
 */
export function RecipientRow({
  recipient,
  selected,
  onSelect,
}: {
  recipient: Recipient
  selected: boolean
  onSelect: () => void
}) {
  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault()
      onSelect()
    }
  }

  return (
    <div
      role="button"
      tabIndex={0}
      aria-pressed={selected}
      onClick={onSelect}
      onKeyDown={onKeyDown}
      style={{
        display: "flex",
        alignItems: "center",
        gap: "var(--atlas-spacing-3)",
        padding: "var(--atlas-spacing-3)",
        borderRadius: "var(--atlas-radius-lg)",
        border: `var(--atlas-border-width-1) solid ${selected ? "var(--atlas-primary)" : "var(--atlas-border)"}`,
        background: selected ? "var(--atlas-primary-subtle)" : "var(--atlas-surface)",
        cursor: "pointer",
        transition: "border-color var(--atlas-duration-fast) var(--atlas-easing-standard), background var(--atlas-duration-fast) var(--atlas-easing-standard)",
      }}
    >
      <span
        aria-hidden="true"
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          inlineSize: "var(--atlas-spacing-10)",
          blockSize: "var(--atlas-spacing-10)",
          borderRadius: "var(--atlas-radius-full)",
          background: "var(--atlas-background-muted)",
          color: "var(--atlas-foreground-muted)",
          fontSize: "var(--atlas-font-size-sm)",
          fontWeight: "var(--atlas-font-weight-semibold)",
          flexShrink: 0,
        }}
      >
        {recipient.initials}
      </span>
      <span style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-0_5)", flex: 1, minInlineSize: 0 }}>
        <span style={{ fontSize: "var(--atlas-font-size-sm)", fontWeight: "var(--atlas-font-weight-medium)", color: "var(--atlas-foreground)" }}>
          {recipient.name}
        </span>
        <span style={{ fontSize: "var(--atlas-font-size-xs)", color: "var(--atlas-foreground-subtle)" }}>
          {recipient.accountMasked}
        </span>
      </span>
      <Badge variant="secondary" size="sm">
        {recipient.currency}
      </Badge>
    </div>
  )
}

export function SummaryRow({ label, value }: { label: string; value: string }) {
  return (
    <div style={{ display: "flex", justifyContent: "space-between", gap: "var(--atlas-spacing-4)" }}>
      <span style={{ fontSize: "var(--atlas-font-size-sm)", color: "var(--atlas-foreground-muted)" }}>{label}</span>
      <span style={{ fontSize: "var(--atlas-font-size-sm)", color: "var(--atlas-foreground)", fontWeight: "var(--atlas-font-weight-medium)" }}>
        {value}
      </span>
    </div>
  )
}

