"use client"

import { useMemo, useState } from "react"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { Label } from "@atlas/ui-web/primitives/Label/Label"
import { RECENT_RECIPIENTS } from "../schema"
import type { SendMoneyStepProps } from "../schema"
import { RecipientRow } from "./_parts"

export function Recipient({ data, patch, next }: SendMoneyStepProps) {
  const [query, setQuery] = useState("")

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase()
    if (!q) return RECENT_RECIPIENTS
    return RECENT_RECIPIENTS.filter((r) => r.name.toLowerCase().includes(q))
  }, [query])

  const select = (id: string) => {
    patch({ recipientId: id })
    next()
  }

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "var(--atlas-spacing-5)",
        paddingInline: "var(--atlas-spacing-4)",
        paddingBlockStart: "var(--atlas-spacing-4)",
      }}
    >
      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-1)" }}>
        <h1 style={{ fontSize: "var(--atlas-text-h3)", fontWeight: "var(--atlas-font-weight-semibold)", margin: 0 }}>
          Who are you sending to?
        </h1>
        <p style={{ fontSize: "var(--atlas-font-size-sm)", color: "var(--atlas-foreground-muted)", margin: 0 }}>
          Search or pick a recent recipient.
        </p>
      </div>

      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-1_5)" }}>
        <Label htmlFor="recipient-search" size="sm">
          Search recipients
        </Label>
        <Input
          id="recipient-search"
          variant="default"
          size="md"
          placeholder="Name"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
        />
      </div>

      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-2)" }}>
        <span style={{ fontSize: "var(--atlas-font-size-xs)", color: "var(--atlas-foreground-subtle)", fontWeight: "var(--atlas-font-weight-medium)" }}>
          Recent
        </span>
        {filtered.length === 0 ? (
          <p style={{ fontSize: "var(--atlas-font-size-sm)", color: "var(--atlas-foreground-muted)" }}>
            No recipients match &ldquo;{query}&rdquo;.
          </p>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-2)" }}>
            {filtered.map((r) => (
              <RecipientRow key={r.id} recipient={r} selected={data.recipientId === r.id} onSelect={() => select(r.id)} />
            ))}
          </div>
        )}
      </div>
    </div>
  )
}

